package com.careflow.hospital.appointments;
import jakarta.persistence.LockModeType;import java.time.Instant;import java.util.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;
public interface AppointmentRepository extends JpaRepository<Appointment,UUID>{@Query("select a from Appointment a where a.doctorId=:doctorId and a.status in ('REQUESTED','CONFIRMED','CHECKED_IN','IN_PROGRESS') and a.startsAt < :end and a.endsAt > :start")List<Appointment> findActiveOverlaps(@Param("doctorId")UUID doctorId,@Param("start")Instant start,@Param("end")Instant end);List<Appointment> findAllByPatientIdOrderByStartsAtDesc(UUID patientId);List<Appointment> findAllByDoctorIdOrderByStartsAtDesc(UUID doctorId);@Lock(LockModeType.PESSIMISTIC_WRITE)@Query("select a from Appointment a where a.id=:id")Optional<Appointment> findByIdForUpdate(@Param("id")UUID id);}
